from lib import *
S = SS('m11')
steps = [
    step("--wiredTigerCacheSizeGB 0.25(最小值)时 serverStatus 给出的缓存上限是 268,435,456 字节(256.0 MB),以及淘汰阈值:缓存占用的目标 80%、触发 95%;脏数据的目标 5%、触发 20%;含更新的页目标 2.5%、触发 10%。", t=tl(S(1)), mark=lidx(S(1), 'cache full', 'dirty'), done=lidx(S(1), 'maximum bytes configured', 'updates'), kv=KV([['缓存上限', '256 MB(0.25 GB)'], ['占用 80% / 95%', '开始 / 强制淘汰'], ['脏数据 5% / 20%', '开始 / 强制淘汰'], ['更新 2.5% / 10%', '含更新的页']], ['占用 80% / 95%'])),
    step("装入 500,000 个文档(每个约 1.2 KB 随机字节,586.0 MB,是缓存的两倍多)只用 3.9 秒(127,890 个/秒),每批 1000 个的延迟中位数 3.44 ms、p99 11.13 ms;采样到的缓存占用峰值 205.6 MB(没超过 256.0 MB 的上限),结束时 159.4 MB;期间写出 7,416 个页,淘汰了 599 个未修改页和 361 个已修改页,应用线程自己做的淘汰为 0。", t=tl(S(2)), mark=lidx(S(2), '采样到的缓存占用峰值', '装入期间'), done=lidx(S(2), '耗时', '集合 dataSize'), kv=KV([['缓存占用', '峰值 205.6 MB < 256 MB'], ['淘汰', '由后台线程完成,应用线程 0'], ['装入速度', '127,890 个/秒']], ['缓存占用'])),
    step("工作集小于缓存:只读前 50,000 个文档(约 60 MB),预热后 20,000 次随机读,9,551 次/秒,中位数 0.10 ms、p99 0.18 ms,期间读入缓存的页只有 17(每次读 0.00 页)。", t=tl(S(3)), mark=lidx(S(3), '工作集 60 MB'), done=lidx(S(3), '17'), kv=KV([['读入缓存的页', '17 / 20,000 次读'], ['p99', '0.18 ms']], ['读入缓存的页'])),
    step("工作集大于缓存:在全部 500,000 个文档里随机读,20,000 次读 7,247 次/秒,期间读入缓存 12,453 个页,平均每次读 0.62 页;再来一轮 7,411 次/秒、每次读 0.63 页,这一轮淘汰了 14,151 个未修改页、0 个已修改页。延迟中位数 0.14 ms(对工作集小于缓存时的 0.10 ms)。", t=tl(S(4)), mark=lidx(S(4), '工作集 600 MB / 缓存 256 MB', '再来一轮', '这一轮的淘汰'), done=lidx(S(4), ' '), b=bars([['工作集 60 MB', 17, '17 页 / 2 万次读'], ['工作集 600 MB', 12453, '12,453 页 / 2 万次读']], 12453, mark=[1], done=[0]), kv=KV([['工作集 > 缓存', '平均每次读 0.62 页要读入'], ['被淘汰的页', '全是未修改页(读场景)'], ['延迟', '中位数 0.10 → 0.14 ms']], ['工作集 > 缓存'])),
    step("同样的 600 MB 工作集,缓存加大到 2 GB(重启后先读一遍预热):缓存占用 652.3 MB,20,000 次随机读 8,994 次/秒,中位数 0.10 ms,读入缓存的页 0。对比 256 MB 缓存的 7,247 次/秒,吞吐只差 24%——磁盘文件被操作系统缓存着,“读入”没有真的读磁盘(没有单独测冷磁盘)。", t=tl(S(5)), mark=lidx(S(5), '工作集 600 MB / 缓存 2 GB'), done=lidx(S(5), '预热后缓存占用'), b=bars([['缓存 256 MB', 7247, '7,247 次/秒'], ['缓存 2 GB', 8994, '8,994 次/秒']], 8994, mark=[0], done=[1]), kv=KV([['缓存 2 GB', '装得下,读入页 0'], ['吞吐', '7,247 → 8,994 次/秒'], ['注意', '操作系统文件缓存让“读盘”很便宜']], ['注意'])),
    step("持续更新随机文档(每次改 1 KB 随机字节)的单线程压力下,2 GB 缓存 9,141 次/秒、256 MB 缓存 8,463 次/秒,两者的 p99 都是 0.24~0.26 ms,应用线程做的淘汰都是 0;但 256 MB 缓存读入的页多得多(50,196 对 11,094)。", t=tl(S(6)), mark=lidx(S(6), '缓存 256 MB'), done=lidx(S(6), '缓存 2 GB'), kv=KV([['吞吐', '9,141 对 8,463 次/秒'], ['应用线程淘汰', '都是 0'], ['读入缓存的页', '11,094 对 50,196']], ['读入缓存的页'])),
    step("8 个线程同时 insert_many(每批 1000 个 1.2 KB 文档)持续 8 秒:2 GB 缓存写入 1,465,000 个(214 MB/s),脏数据峰值 197.5 MB(缓存的 10%),应用线程淘汰耗时 2 ms;256 MB 缓存写入 1,363,000 个(200 MB/s),脏数据峰值 26.1 MB(同样是缓存的 10%),应用线程淘汰耗时 514 ms,每批延迟 p99 107.93 ms 对 93.98 ms。缓存压低后脏数据按比例封顶,吞吐只低约 7%。", t=tl(S(7)), mark=lidx(S(7), 'cache256MB'), done=lidx(S(7), 'cache2GB'), b=bars([['缓存 2 GB 脏数据峰值', 100, '197.5 MB (10%)'], ['缓存 256 MB 脏数据峰值', 13.2, '26.1 MB (10%)'], ['256 MB 应用线程淘汰耗时', 100, '514 ms'], ['2 GB 应用线程淘汰耗时', 0.4, '2 ms']], 100, mark=[1, 2], done=[0, 3]), kv=KV([['脏数据', '约占缓存的 10%'], ['应用线程被迫淘汰', '256 MB:514 ms,2 GB:2 ms'], ['吞吐', '200 对 214 MB/s']], ['应用线程被迫淘汰'])),
]
A = mkartm('m11', 11, 'MongoDB,WiredTiger,缓存,eviction,cacheSizeGB,真实验证,动画演示',
    '实测把 WiredTiger 缓存压到最小的 256 MB:装入两倍于缓存的数据时缓存占用不超过上限;工作集大于缓存时每次读平均要读入 0.62 个页;8 线程写入压力下脏数据封顶在缓存的 10%,应用线程被迫淘汰的耗时从 2 ms 增到 514 ms,吞吐只低约 7%;serverStatus 里直接给出淘汰阈值。',
    '把 cacheSizeGB 压到最低,数据比缓存大几倍时,WiredTiger 的 eviction 到底怎么表现?这篇装入 586 MB 数据,分别测工作集小于缓存、大于缓存、缓存加大到 2 GB,再用 8 线程写入压力看脏数据和应用线程淘汰。',
    [('256 MB', '缓存最小值(0.25 GB),淘汰目标 80%、触发 95%,脏数据目标 5%、触发 20%'), ('17 → 12,453', '读 2 万次时读入缓存的页:工作集 60 MB 与 600 MB(缓存 256 MB)'), ('514 ms', '8 线程写入压力下 256 MB 缓存里应用线程淘汰的总耗时(2 GB 缓存只有 2 ms)')],
    [('阈值', '<p><code>serverStatus().wiredTiger.cache</code> 直接给出阈值:占用超过 80% 后台线程开始淘汰,95% 时应用线程被迫帮忙;脏数据 5% / 20%,含更新的页 2.5% / 10%。</p>'),
     ('装入超过缓存的数据', '<p>586 MB 的数据装入 256 MB 的缓存,占用峰值 205.6 MB,没有越界;期间淘汰了未修改与已修改页,但全由后台线程完成。</p>'),
     ('工作集小于缓存', '<p>只读 60 MB 的热数据时,预热后 2 万次随机读只读入 17 个页,中位数 0.10 ms。</p>'),
     ('工作集大于缓存', '<p>在全部 586 MB 里随机读,平均每次读要读入约 0.62 个页,同时淘汰别的页(读场景下淘汰的全是未修改页)。</p>'),
     ('加大缓存', '<p>缓存 2 GB 时 600 MB 的工作集全部装得下,读入的页为 0,吞吐比 256 MB 时高约 24%——差距不大,因为操作系统缓存了文件。</p>'),
     ('单线程更新', '<p>单线程持续更新时,256 MB 与 2 GB 缓存的吞吐和延迟接近,应用线程都没有被迫淘汰,只是小缓存读入的页多得多。</p>'),
     ('写入压力', '<p>脏数据始终被封顶在缓存的约 10%,小缓存下脏数据峰值只有 26.1 MB。应用线程被迫淘汰的耗时从 2 ms 增加到 514 ms,但吞吐只低约 7%。本机是快速 SSD、操作系统文件缓存充裕,小缓存的代价主要体现在读入的页数和后台淘汰上,延迟变化不大;慢盘上结论可能不同。</p>')],
    steps,
    [ENV_M + '。缓存用 --wiredTigerCacheSizeGB 0.25 和 2 控制(重启切换);数据是不可压缩的随机字节,避免压缩影响;缓存指标都来自 serverStatus().wiredTiger.cache',
     '没有验证:慢磁盘或冷操作系统缓存下的读延迟;缓存占用到 95% 以上、应用线程大量淘汰的极端情况(本实验中没有触发);cacheSizeGB 之外的内存占用(连接、排序、聚合);Linux 上的内存压力;checkpoint 对脏数据的影响;history store(WiredTigerHS.wt)对缓存的占用'],
    'WiredTiger 缓存与淘汰')
